insert into public.products(slug,name,category,description,composition,image,price_amd,price_unit,sort_order) values ('floral-jelly','Ծաղիկներ ժելեի մեջ','Ժելե','Թափանցիկ ժելե և ծաղկային կոմպոզիցիա՝ նվերի ու ընտանեկան տոնի համար։','Օրինակային համ՝ վանիլային ժելե, կաթնային շերտ, հատապտղային նոտաներ։ Բաղադրությունը ճշտվում է պատվիրելիս։','assets/cake-2.webp',6500,'կգ',1),('snickers','Սնիկերս','Բիսկվիթային','Շոկոլադ, կարամել և արախիս՝ հարուստ ու հավասարակշռված համի համար։','Օրինակային միջուկ՝ շոկոլադե բիսկվիթ, կարամել, բոված արախիս, սերուցքային կրեմ։ Պարունակում է ընկույզ, կաթնամթերք, ձու և գլյուտեն։','assets/cake-3.webp',5500,'կգ',2),('strawberry-banana','Ելակ և բանան','Մրգային','Թեթև մրգային համադրություն՝ մեղմ կրեմով ու նուրբ բիսկվիթով։','Օրինակային միջուկ՝ վանիլային բիսկվիթ, ելակ, բանան, սերուցքային կրեմ։ Պարունակում է կաթնամթերք, ձու և գլյուտեն։','assets/cake-1.webp',5000,'կգ',3);
insert into public.courses(slug,title,summary,description,image,duration_minutes,price_amd,level,outcomes,sort_order) values ('snickers-masterclass','Սնիկերս․ շերտ առ շերտ','Շոկոլադե բիսկվիթից մինչև հավաքում ու ձևավորում։ Մեկ դաս՝ ձեր տեմպով։','Դասընթացի ցուցադրական օրինակ։ Այստեղ կարող է լինել ArS-ի հեղինակային տեսադասը՝ ամբողջ պատրաստման ընթացքով, բացատրություններով և բաղադրիչների ցանկով։ Ներկայում օգտագործվում է երրորդ կողմի բաց տեսանյութի հատված՝ միայն հարթակի աշխատանքը ցույց տալու համար։','assets/cake-3.webp',45,10000,'Սկսնակ և միջին','["Աշխատավայրի և գործիքների նախապատրաստում", "Բիսկվիթի ու միջուկի պատրաստման սկզբունքներ", "Շերտերի հավասար հավաքում", "Կրեմով ծածկում և ավարտական ձևավորում"]'::jsonb,1);
insert into public.site_settings(id,payment_bank,payment_account,payment_recipient,payment_phone,payment_note) values (1,'DEMO BANK · ԳՈՅՈՒԹՅՈՒՆ ՉՈՒՆԵՑՈՂ ԲԱՆԿ','0000 0000 0000 0000','ՑՈՒՑԱԴՐԱԿԱՆ ՍՏԱՑՈՂ','+37477261090','ՄԻ ՓՈԽԱՆՑԵՔ ԳՈՒՄԱՐ։ Բոլոր վճարային տվյալները հորինված են։ Այս էջը ցուցադրում է հայտի և ձեռքով հաստատման ընթացքը։');
insert into public.lessons(course_id,video_id,description,ingredients,chapters) select id,'Ra0przfB2uk','Ցուցադրական տեսանյութ՝ Doce na Medida ալիքից, «How to Assemble a Celebration Cake»։ Ցուցադրվում է առաջին 45 րոպեանոց հատվածը։ Սա ArS-ի հեղինակային կամ վաճառվող դասընթացը չէ։ Ստորև բերված ցանկերը միայն ապագա դասի էջի օրինակ են և չեն ներկայացվում որպես տեսանյութի բաղադրատոմս։','["Շոկոլադե բիսկվիթի շերտեր — օրինակ", "Կարամել և բոված արախիս — օրինակ", "Սերուցքային կրեմ — օրինակ", "Շոկոլադ և ձևավորման նյութեր — օրինակ"]'::jsonb,'["Նախապատրաստում և գործիքներ", "Բիսկվիթ ու միջուկ", "Հավաքում և հավասարեցում", "Վերջնական ձևավորում"]'::jsonb from public.courses where slug='snickers-masterclass';
